{{ config(materialized='table') }}
SELECT
    customer_hk,
    customer_id
FROM (
    SELECT
        customer_hk,
        customer_id,
        ROW_NUMBER() OVER (
            PARTITION BY customer_hk
            ORDER BY __source_ordinal
        ) AS __rn
    FROM (
        SELECT DISTINCT
            lower(hex(SHA256(upper(trim(cast(customer_id as String)))))) AS customer_hk,
            upper(trim(cast(customer_id as String))) AS customer_id,
            0 AS __source_ordinal
        FROM {{ ref('stg_customers_crm') }}
        WHERE customer_id IS NOT NULL
        UNION ALL
        SELECT DISTINCT
            lower(hex(SHA256(upper(trim(cast(customer_id as String)))))) AS customer_hk,
            upper(trim(cast(customer_id as String))) AS customer_id,
            1 AS __source_ordinal
        FROM {{ ref('stg_customers_web') }}
        WHERE customer_id IS NOT NULL
    ) AS combined
) AS ranked
WHERE __rn = 1
